import { NextResponse, type NextRequest } from "next/server";

const LAYERS = new Set(["districts", "sections", "sectors", "neighbourhoods", "streets", "facilities"]);

/**
 * Mapbox Vector Tiles generated by PostGIS (`public.location_tile`, ST_AsMVT).
 * Boundary tiles hold only names and codes, so they are served with the anon key and
 * cached briefly at the edge. Parcel layers (Phase 4) get their own authenticated route.
 */
export async function GET(
  _req: NextRequest,
  { params }: { params: Promise<{ layer: string; z: string; x: string; y: string }> },
) {
  const { layer, z, x, y } = await params;
  const zi = Number(z);
  const xi = Number(x);
  const yi = Number(y.replace(/\.(pbf|mvt)$/, ""));
  if (!LAYERS.has(layer) || ![zi, xi, yi].every(Number.isInteger) || zi < 0 || zi > 22) {
    return new NextResponse(null, { status: 400 });
  }
  const max = 2 ** zi;
  if (xi < 0 || yi < 0 || xi >= max || yi >= max) return new NextResponse(null, { status: 400 });

  const url = process.env.NEXT_PUBLIC_SUPABASE_URL;
  const key = process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY;
  if (!url || !key) return new NextResponse(null, { status: 503 });

  const res = await fetch(`${url}/rest/v1/rpc/location_tile`, {
    method: "POST",
    headers: {
      apikey: key,
      Authorization: `Bearer ${key}`,
      "content-type": "application/json",
    },
    body: JSON.stringify({ p_layer: layer, p_z: zi, p_x: xi, p_y: yi }),
    next: { revalidate: 300 },
  });
  if (!res.ok) return new NextResponse(null, { status: 502 });

  // PostgREST returns bytea as a JSON string of hex ("\\x1a2b…").
  const hex = (await res.json()) as string | null;
  const body = Buffer.from((hex ?? "").replace(/^\\x/, ""), "hex");
  if (body.byteLength === 0) return new NextResponse(null, { status: 204, headers: { "cache-control": "public, max-age=300" } });
  return new NextResponse(body, {
    headers: {
      "content-type": "application/vnd.mapbox-vector-tile",
      "cache-control": "public, max-age=300, s-maxage=600, stale-while-revalidate=3600",
    },
  });
}
